#!/usr/bin/env node
/**
 * Downloads the seven BlueStep One `.d.ts` files into a types folder and checks each one.
 *
 *   node fetch-types.mjs [--host <host>] [--out <dir>]
 *
 * The files are generated by the running tenant and served at
 * `https://<host>/one/<name>.d.ts`. `<host>` is `one.host` of `.claude/bluestep-one.json` in
 * the cwd, or `--host`. `<dir>` is `--out`, default `types` under the cwd. Never edit the files:
 * the next download overwrites them.
 *
 * Banner check, per file: it opens with a `/**` doc comment, the first lines of that comment carry
 * the word GENERATED, and the file has a top-level `export`. A wrong path answers 200 with
 * `index.html`, and with `skipLibCheck` on that would turn into silent `any`, so a file that fails
 * is not kept. (Do not grep the body for `<html`: the ui types mention `HTMLElement`.)
 *
 * Exit 0 when all seven pass, 1 when any fails, 2 on bad usage.
 */

import { existsSync, mkdirSync, readFileSync, writeFileSync } from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

export const NAMES = ["component-host", "form-kit", "ui", "ui.primitives", "ui.structural", "ui.tokens", "ui.icons"];

/** `null` when the text passes the banner check, else the reason it fails. */
export function bannerProblem(text) {
  const body = text.replace(/^﻿/, "").trimStart();
  if (!body.startsWith("/**")) return "does not open with a /** doc comment";
  const head = body.split(/\r?\n/).slice(0, 12).join("\n");
  if (!/GENERATED/.test(head)) return "the opening comment has no GENERATED banner";
  if (!/^export\b/m.test(body)) return "has no top-level export";
  return null;
}

/** Downloads every name with `fetchFn`, writes the ones that pass, returns `[{ name, ok, detail }]`. */
export async function fetchTypes({ host, out, fetchFn = fetch }) {
  mkdirSync(out, { recursive: true });
  const results = [];
  for (const name of NAMES) {
    const url = `https://${host}/one/${name}.d.ts`;
    try {
      const res = await fetchFn(url);
      if (!res.ok) {
        results.push({ name, ok: false, detail: `HTTP ${res.status} from ${url}` });
        continue;
      }
      const text = await res.text();
      const problem = bannerProblem(text);
      if (problem) {
        results.push({ name, ok: false, detail: `${problem} (${url})` });
        continue;
      }
      writeFileSync(path.join(out, `${name}.d.ts`), text);
      results.push({ name, ok: true, detail: "" });
    } catch (cause) {
      results.push({ name, ok: false, detail: `${url}: ${cause.message}` });
    }
  }
  return results;
}

function configHost() {
  try {
    const file = path.join(process.cwd(), ".claude", "bluestep-one.json");
    if (!existsSync(file)) return undefined;
    return JSON.parse(readFileSync(file, "utf8"))?.one?.host || undefined;
  } catch {
    return undefined;
  }
}

async function main(argv) {
  const opt = (name) => {
    const i = argv.indexOf(`--${name}`);
    return i >= 0 ? argv[i + 1] : undefined;
  };
  const host = (opt("host") ?? configHost() ?? "").replace(/^https?:\/\//, "").replace(/\/$/, "");
  const out = path.resolve(opt("out") ?? "types");
  if (!host) {
    console.error("usage: node fetch-types.mjs [--host <host>] [--out <dir>]");
    console.error("no host: pass --host or set one.host in .claude/bluestep-one.json");
    return 2;
  }
  const results = await fetchTypes({ host, out });
  for (const r of results) console.log(`${r.ok ? "ok  " : "BAD "} ${r.name}.d.ts${r.detail ? `: ${r.detail}` : ""}`);
  return results.every((r) => r.ok) ? 0 : 1;
}

if (process.argv[1] && path.resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  process.exit(await main(process.argv.slice(2)));
}
